/// Count newline-terminated lines. Files without a trailing newline still
/// count their last line (matches `wc -l` semantics for non-empty files).
async fn count_lines(path: &Path) -> std::io::Result<u64> {
    let file = tokio::fs::File::open(path).await?;
    let reader = BufReader::new(file);
    let mut count: u64 = 0;
    let mut lines = reader.lines();
    while let Some(line) = lines.next_line().await? {
        // Surface I/O errors (e.g. invalid UTF-8 in a "text" file) so the
        // caller can mark the file as skipped instead of double-counting.
        let _ = line;
        count += 1;
    }
    Ok(count)
}

findings.after:
/// Count newline-terminated lines. Files without a trailing newline still
/// count their last line (matches `wc -l` semantics for non-empty files).
async fn count_lines(path: &Path) -> std::io::Result<u64> {
    // spawn_blocking: the count is a tight byte-scanning loop that pins the
    // current tokio worker for the duration of the read. On a 16 MB file the
    // loop is small, but a `stats **/*` over thousands of large files
    // serialises every read on one worker and starves the rest of the runtime.
    let p = path.to_path_buf();
    tokio::task::spawn_blocking(move || -> std::io::Result<u64> {
        use std::io::{BufRead, BufReader};
        let f = std::fs::File::open(&p)?;
        let mut count: u64 = 0;
        for _ in BufReader::new(f).lines() {
            count += 1;
        }
        Ok(count)
    })
    .await
    .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e.to_string()))?
}

